# Generated by Claude Sonnet 4.5
"""Backfill thumbnail paths for existing videos in DuckDB.

Scans all videos in the database and associates thumbnails from
data/torah_read/מגילות/ based on playlist name and alya order_num.

Usage:
    uv run python scripts/backfill_thumbnails.py --dry-run  # Preview changes
    uv run python scripts/backfill_thumbnails.py --apply    # Apply changes
"""

import argparse
import sys
from pathlib import Path

from src.lib.logging import get_logger
from src.models.playlist import PlaylistType
from src.repositories.alya_repo import AlyaRepository
from src.repositories.alya_video_repo import AlyaVideoRepository
from src.repositories.playlist_repo import PlaylistRepository
from src.services.local_thumbnail_service import LocalThumbnailService

logger = get_logger(__name__)


def backfill_thumbnails(*, dry_run: bool = True) -> tuple[int, int]:
    """Find and associate thumbnails for all existing videos.

    Args:
        dry_run: If True, preview changes without writing to database.

    Returns:
        Tuple of (videos_updated, videos_skipped).
    """
    video_repo = AlyaVideoRepository()
    alya_repo = AlyaRepository()
    playlist_repo = PlaylistRepository()
    thumbnail_service = LocalThumbnailService()

    # Get all videos
    all_videos = video_repo.list_all()
    logger.info(f"Found {len(all_videos)} videos in database")

    updated = 0
    skipped = 0

    for video in all_videos:
        # Get alya and playlist info
        alya = alya_repo.get_by_id(video.alya_id)
        if not alya:
            logger.warning(f"Video {video.id}: alya {video.alya_id} not found")
            skipped += 1
            continue

        playlist = playlist_repo.get_by_id(alya.playlist_id)
        if not playlist:
            logger.warning(f"Video {video.id}: playlist {alya.playlist_id} not found")
            skipped += 1
            continue

        # Skip if not a megillah
        if playlist.playlist_type != PlaylistType.MEGILLAH:
            logger.debug(f"Video {video.id}: playlist {playlist.name} is not a megillah (skipping)")
            skipped += 1
            continue

        # Skip if already has thumbnail
        if video.thumbnail_path:
            existing_path = Path(video.thumbnail_path)
            if existing_path.exists():
                logger.debug(f"Video {video.id}: already has valid thumbnail (skipping)")
                skipped += 1
                continue
            else:
                logger.warning(f"Video {video.id}: has thumbnail path but file missing: {video.thumbnail_path}")

        # Find thumbnail
        thumbnail_path = thumbnail_service.find_thumbnail(playlist, alya)
        if thumbnail_path:
            logger.info(f"Video {video.id}: {playlist.name} - {alya.name} → {thumbnail_path.name}")

            if not dry_run:
                video.thumbnail_path = str(thumbnail_path)
                video_repo.update(video)
                logger.info(f"  ✓ Updated video {video.id}")
            else:
                logger.info(f"  [DRY RUN] Would update video {video.id}")

            updated += 1
        else:
            logger.warning(f"Video {video.id}: {playlist.name} - {alya.name} → thumbnail not found")
            skipped += 1

    return updated, skipped


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Backfill thumbnail paths for existing videos."
    )
    parser.add_argument(
        "--apply",
        action="store_true",
        help="Apply changes to database (default: dry-run)",
    )
    args = parser.parse_args()

    dry_run = not args.apply
    mode = "DRY RUN" if dry_run else "APPLYING CHANGES"

    print(f"\n{'='*60}")
    print(f"Thumbnail Backfill - {mode}")
    print(f"{'='*60}\n")

    updated, skipped = backfill_thumbnails(dry_run=dry_run)

    print(f"\n{'='*60}")
    print(f"Summary:")
    print(f"  Videos updated: {updated}")
    print(f"  Videos skipped: {skipped}")

    if dry_run and updated > 0:
        print(f"\n  Re-run with --apply to save changes to database")
    elif not dry_run and updated > 0:
        print(f"\n  ✓ Changes saved to database")

    print(f"{'='*60}\n")


if __name__ == "__main__":
    main()
